import { JSONSchemaCustom, SchemaApiJsonPage } from "@/components/schema";
import { AllSchema } from "@/components/schema/Page";
import { itemCodes } from "@/types/app";
import React, { useMemo } from "react";

// 插件管理
const Plugins = () => {

    const schema = useMemo(() => {
        const allSchema: AllSchema = {
            "type": "object",
            "properties": {
                "id": {
                    "type": "string",
                    "title": "插件ID",
                    "columnProps": {
                        width: 150
                    }
                },
                "name": {
                    "type": "string",
                    "title": "插件名称"
                },
                "platform": {
                    "type": "string",
                    "title": "插件模块",
                    // "format": "radio",
                    "enum": [
                        "taro",
                        "pc",
                        "dashboard"
                    ],
                    "default": "pc"
                },
                "sort": {
                    "title": "插件排序",
                    "type": "integer"
                },
                "isActive": {
                    "type": "string",
                    "format": "radio",
                    "enum": [
                        { value: 1, label: "启用", color: "arcoblue" },
                        { value: 0, label: "停用", color: "red" }
                    ],
                    "title": "状态",
                },
                "PluginProject": {
                    "type": "array",
                    "title": "适用项目",
                    "format": "selector",
                    "fieldProps": {
                        "type": "project",
                        "mode": "multiple"
                    },
                    "table": {
                        "format": "tags",
                        "fieldProps": {
                            "labelField": "name"
                        }
                    }
                },
                "description": {
                    "type": "string",
                    "format": "text",
                    "title": "插件描述"
                }
            },
            "required": ["id", "name", "sort"]
        };


        return allSchema;
    },[])


    return (
        <SchemaApiJsonPage
            apijson={{
                tableName: "Plugins",
                uniqueKey: "id",
                findParams: {
                    "@order": "sort+"
                }
            }}
            eidtProps={{
                disbledKeys: ["id"]
            }}
            getOperationList={(list, item) => {

                return [
                    {
                        title: "开发",
                        onClick: () => {
                            window.open(`#/plugin/${item.id}/`)
                        }
                    },
                    ...list,
                ]
            }}
            joins={[
                {
                    type: "ToMany",
                    tableName: "Project",
                    columns: ['id', 'name'],
                    foreignKey: "id",
                    relationKey: "id",
                    toTableName: "PluginProject",
                    toTableKey: "id",
                    toForeignKey: "projectId",
                    toRelationKey: "pluginId"
                }
            ]}
            schema={schema}
        ></SchemaApiJsonPage>
    )

}

export default Plugins;